    bankManualS1Title: '1. แท็บบันทึก – อัปโหลด CSV',
    bankManualS1_1: 'เลือกบัญชี → คลิกอัปโหลด CSV ธนาคาร → เลือก CSV รูปแบบ K-DEPOSIT',
    bankManualS1_2: 'ตรวจสอบประเภท บัญชี วันที่ขาย วันที่ค่าใช้จ่ายในการแสดงตัวอย่างแล้วบันทึก',
    bankManualS1_3: 'รายการซ้ำ (วันที่ จำนวน หมายเหตุเดียวกัน) ถูกข้ามอัตโนมัติ',
    bankManualS1_4: 'ไม่มีบัญชี? เพิ่มด้วยชื่อธนาคาร ชื่อบัญชี ร้านค้า',
    bankManualS2Title: '2. แท็บค้นหา – ค้นหาและกรอง',
    bankManualS2_1: 'เลือกบัญชีและช่วงเวลา → ค้นหา → แสดงรายการ',
    bankManualS2_2: 'ใส่ยอดจริงเพื่อเปรียบเทียบกับระบบ (ตรวจสอบถ้าไม่ตรง)',
    bankManualS2_3: 'กรอง: ประเภท(ฝาก/ถอน) ประเภท รหัสบัญชี เฉพาะใบแจ้งหนี้ยังไม่ได้รับ',
    bankManualS2_4: 'ตรวจสอบใบแจ้งหนี้: คลิกไอคอนในรายการชำระค่าซื้อ → เช็คการรับ (ซิงค์กับใบสั่งซื้อ)',
    bankManualS3Title: '3. การฝาก – จับคู่อัตโนมัติ',
    bankManualS3_1: 'ประเภท: เดลิเวอรี่ บัตร QR/โอน เงินสด รับชำระ ตามคำสำคัญหมายเหตุ',
    bankManualS3_2: 'บัญชี: Grab Line Man Shopee Visa Master ฯลฯ จับคู่อัตโนมัติ',
    bankManualS3_3: 'รับชำระ: เลือกผู้รับ (ร้านหรือผู้ขาย) → ลูกหนี้หักอัตโนมัติ',
    bankManualS3_4: 'วันที่ขาย: วันที่ฝาก -1 วัน (T+1) ตามค่าเริ่มต้น',
    bankManualS4Title: '4. การถอน – จับคู่อัตโนมัติ',
    bankManualS4_1: 'ประเภท: เติม/โอน คงที่ (ค่าเช่า ค่าไฟ เงินเดือน) ค่าใช้จ่าย',
    bankManualS4_2: 'ชำระค่าซื้อ: เลือกผู้ขาย → เจ้าหนี้หักอัตโนมัติ',
    bankManualS4_3: 'กู้ยืม ล่วงหน้า ยังไม่จำแนก: ไม่นับในกำไรขาดทุน (จัดภายหลัง)',
    bankManualS4_4: 'บัญชี: ค่าเช่า ค่าไฟฟ้า เงินเดือน ฯลฯ ตามคำสำคัญ',
    bankManualS4_5: 'วันที่ค่าใช้จ่าย: ว่าง = ใช้วันชำระ',
    bankManualS5Title: '5. ลูกหนี้/เจ้าหนี้',
    bankManualS5_1: 'รับชำระ (ฝาก) + เลือกผู้รับ → ลูกหนี้ร้าน/ผู้ขายหัก',
    bankManualS5_2: 'ชำระค่าซื้อ (ถอน) + เลือกผู้ขาย → เจ้าหนี้ผู้ขายหัก',
    bankManualS6Title: '6. ตรวจสอบใบแจ้งหนี้',
    bankManualS6_1: 'ธนาคาร > ค้นหา: คลิกไอคอนรายการชำระค่าซื้อเพื่อเช็คการรับ',
    bankManualS6_2: 'ถ้าเชื่อมใบสั่งซื้อ เช็คด้านใดด้านหนึ่งจะซิงค์ทั้งคู่',
    bankManualS6_3: 'ซื้อโดยตรง (ไม่มีใบสั่ง เช่น ซูเปอร์มาร์เก็ต) ก็เช็คใบแจ้งหนี้ที่นี่ได้',
    bankManualS7Title: '7. เกณฑ์คงค้าง (วันรับรู้)',
    bankManualS7_1: 'ขายม.ค. รับเงินก.พ. → วันที่ขาย = ม.ค. ซื้อม.ค. จ่ายก.พ. → วันที่ค่าใช้จ่าย = ม.ค. รายงานกำไรขาดทุนใช้วันรับรู้ตามเดือน',
    bankManualS8Title: '8. กฎคำสำคัญหมายเหตุ',
    bankManualS8_1: 'ถ้าหมายเหตุธนาคารมีคำสำคัญ จะกำหนดประเภทและบัญชีอัตโนมัติ เพิ่มกฎด้านล่าง จะทับการจับคู่พื้นฐานเมื่ออัปโหลด CSV',
